-- # Lernfeld 5: Cyberphysische Systeme > ## Testgetriebene Entwicklung > - Dokumentation > - Kriterien

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind klar definierte Kriterien in der TDD-Dokumentation notwendig, um den Erfolg von Tests zu bewerten?', 2, '[{"text": "Ja", "correct": true, "because": "Kriterien definieren Erwartungen"}, {"text": "Nein", "correct": false, "because": "Klarheit ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Kriterien in der TDD-Dokumentation ohne Bezug zu den Tests sinnvoll sein?', 2, '[{"text": "Nein", "correct": true, "because": "Tests und Kriterien verknüpft"}, {"text": "Ja", "correct": false, "because": "Relevanz durch Tests gegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Kriterien in der TDD-Dokumentation immer messbar sein?', 2, '[{"text": "Ja", "correct": true, "because": "Messbarkeit ermöglicht Überprüfung"}, {"text": "Nein", "correct": false, "because": "Messbarkeit ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Kriterien in der TDD-Dokumentation die Wartbarkeit der Tests verbessern?', 2, '[{"text": "Ja", "correct": true, "because": "Klare Kriterien erleichtern Pflege"}, {"text": "Nein", "correct": false, "because": "Wartbarkeit wird unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Kriterien in der TDD-Dokumentation unabhängig von den Projektanforderungen?', 2, '[{"text": "Nein", "correct": true, "because": "Kriterien spiegeln Anforderungen wider"}, {"text": "Ja", "correct": false, "because": "Anforderungen sind Basis"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgen Kriterien in der TDD-Dokumentation?', 2, '[{"text": "Bewertung des Testerfolgs", "correct": true, "because": "Kriterien definieren Erfolg"}, {"text": "Erhöhung der Komplexität", "correct": false, "because": "Nicht Ziel"}, {"text": "Vermeidung von Tests", "correct": false, "because": "Tests zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt der Kriterien in der TDD-Dokumentation ist entscheidend für die Nachvollziehbarkeit?', 3, '[{"text": "Klarheit und Präzision", "correct": true, "because": "Ermöglicht Verständnis"}, {"text": "Hohe Abstraktion", "correct": false, "because": "Weniger hilfreich"}, {"text": "Manuelle Überprüfung", "correct": false, "because": "Automatisierung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium sollte in der TDD-Dokumentation besonders betont werden?', 2, '[{"text": "Messbarkeit", "correct": true, "because": "Überprüfbarkeit wichtig"}, {"text": "Vagheit", "correct": false, "because": "Unklarheit schadet"}, {"text": "Komplexität", "correct": false, "because": "Einfachheit bevorzugt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Kriterien in der TDD-Dokumentation für die Testwartung?', 2, '[{"text": "Erleichterung der Anpassung", "correct": true, "because": "Klare Kriterien helfen"}, {"text": "Verhinderung von Tests", "correct": false, "because": "Tests zentral"}, {"text": "Erhöhung der Laufzeit", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ergibt sich aus gut definierten Kriterien in der TDD-Dokumentation?', 2, '[{"text": "Klarheit für Entwickler", "correct": true, "because": "Verständnis erleichtert"}, {"text": "Weniger Tests", "correct": false, "because": "Tests bleiben nötig"}, {"text": "Schnellere Kompilierung", "correct": false, "because": "Nicht primär"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sollten Kriterien in der TDD-Dokumentation haben?', 4, '[{"text": "Klarheit", "correct": true, "because": "Verständnis erleichtert"}, {"text": "Messbarkeit", "correct": true, "because": "Überprüfung ermöglicht"}, {"text": "Vagheit", "correct": false, "because": "Unklarheit schadet"}, {"text": "Relevanz zu Tests", "correct": true, "because": "Bezug nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten gut definierte Kriterien in der TDD-Dokumentation?', 3, '[{"text": "Nachvollziehbarkeit", "correct": true, "because": "Prozess klar"}, {"text": "Einfachere Testwartung", "correct": true, "because": "Anpassung erleichtert"}, {"text": "Weniger Tests", "correct": false, "because": "Tests bleiben nötig"}, {"text": "Bessere Kommunikation", "correct": true, "because": "Teamverständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sollten Kriterien in der TDD-Dokumentation abdecken?', 3, '[{"text": "Erfolgskriterien für Tests", "correct": true, "because": "Definiert Erwartungen"}, {"text": "Anforderungen des Projekts", "correct": true, "because": "Basis für Tests"}, {"text": "Code-Komplexität", "correct": false, "because": "Nicht primär"}, {"text": "Akzeptanzbedingungen", "correct": true, "because": "Bestimmt Abnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen können bei der Definition von Kriterien in der TDD-Dokumentation auftreten?', 4, '[{"text": "Unklare Anforderungen", "correct": true, "because": "Schwierig zu definieren"}, {"text": "Fehlende Messbarkeit", "correct": true, "because": "Überprüfung erschwert"}, {"text": "Keine Testbezüge", "correct": true, "because": "Relevanz fehlt"}, {"text": "Schnelle Entwicklung", "correct": false, "because": "Nicht Herausforderung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sollten in den Kriterien der TDD-Dokumentation enthalten sein?', 3, '[{"text": "Testziele", "correct": true, "because": "Definiert Fokus"}, {"text": "Erwartete Ergebnisse", "correct": true, "because": "Überprüfbarkeit"}, {"text": "Implementierungsdetails", "correct": false, "because": "Nicht primär"}, {"text": "Akzeptanzkriterien", "correct": true, "because": "Bestimmt Erfolg"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Kriterien in der TDD-Dokumentation müssen messbar sein. b) Kriterien sind in TDD unabhängig von Tests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Messbarkeit nötig, Tests zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Klare Kriterien verbessern die Testwartung. b) Kriterien ersetzen die Notwendigkeit von Tests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wartung erleichtert, Tests bleiben"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kriterien in TDD sollten Anforderungen widerspiegeln. b) Kriterien sind nur für große Projekte relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anforderungen zentral, Größe egal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Kriterien in der TDD-Dokumentation fördern Nachvollziehbarkeit. b) Kriterien müssen komplex sein, um nützlich zu sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nachvollziehbarkeit ja, Einfachheit besser"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kriterien in TDD sollten klar und präzise sein. b) Kriterien sind nur für die Rot-Phase relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Klarheit zentral, alle Phasen betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

